  (23662, 123, 'traits.', 786.120, 790.080, NULL),
  (23663, 123, 'Now, just as a parting thought, I I''m', 787.760, 791.600, NULL),
  (23664, 123, 'very conscious of the fact that as a', 790.080, 793.040, NULL),
  (23665, 123, 'physical scientist, I''m standing here', 791.600, 794.640, NULL),
