  (25652, 130, 'Simple solution: get to the wall,', 144.199, 146.870, NULL),
  (25653, 130, 'kick a ball against
the wall and catch it.', 146.870, 148.494, NULL),
  (25654, 130, 'kick the ball against
the wall and catch it.', 148.494, 150.357, NULL),
