  (26471, 132, '(Laughter)', 711.957, 714.582, NULL),
  (26472, 132, 'Oh wait, one of these is empty, hold on.', 715.754, 719.046, NULL),
  (26473, 132, 'I think this is the one, yep, here you go.', 720.856, 723.459, NULL),
  (26474, 132, 'You get the one that''s disassembled.', 723.459, 725.422, NULL),
  (26475, 132, 'All right, cool.', 725.422, 726.829, NULL),
  (26476, 132, '(Applause)', 726.829, 730.351, NULL),
  (26477, 132, 'I still have a few minutes yet left,
so I''m going to make a couple of points.', 730.351, 734.094, NULL),
  (26478, 132, '(Laughter)', 734.094, 735.025, NULL),
  (26479, 132, 'Oh, shit.', 735.025, 736.512, NULL),
  (26480, 132, 'That''s my subliminal messaging campaign.
It was supposed to be much faster.', 736.512, 741.039, NULL),
  (26481, 132, 'Here''s the most exciting slide
ever shown at TED.', 741.039, 745.209, NULL),
  (26482, 132, 'This is the protocol diagram for SSL,', 745.209, 747.502, NULL),
  (26483, 132, 'which is the encryption
system in your web browser', 747.502, 749.853, NULL),
  (26484, 132, 'that protects your credit card when you''re
sending it to Amazon and so on.', 749.853, 753.324, NULL),
  (26485, 132, 'Very exciting, I know, but the point is', 753.324, 755.341, NULL),
  (26486, 132, 'hackers will attack every
